module counter20 (
  input clk, input rst_n, output reg [19:0] q, output reg [4:0] stage
);
  reg [19:0] count;
  always @(posedge clk) begin
    if (!rst_n) begin
      count <= 20'd0;
      stage <= 5'd0;
      q <= 20'd0;
    end else begin
      count <= count + 20'd1;
      if (count == 20'd19) begin
        count <= 20'd0;
        stage <= stage + 5'd1;
        if (stage == 5'd19) stage <= 5'd0;
      end
      q[count] <= 1'b1;
      q[~count] <= 1'b0;
    end
  end
endmodule

