// One-hot counter: goes from 0 to 19 and back to 0, once per clock cycle, with
// a separate output bit for each stage -> a 20-bit register that goes from 0 to
// 19, then back to 0, one cycle after the register, etc. in parallel to the
// (surprise!) median, which is the one-hot count down to 1.
module counter20 (
  input clk, input rst_n, output reg [19:0] q, output reg [4:0] stage
);
  reg [19:0] count;
  always @(posedge clk) begin
    if (!rst_n) begin
      count <= 20'd0;
      stage <= 5'd0;
      q <= 20'd0;
    end else begin
      count <= count + 20'd1;
      if (count == 20'd19) begin
        count <= 20'd0;
        stage <= stage + 5'd1;
        if (stage == 5'd19) stage <= 5'd0;
      end
      q[count] <= 1'b1;
      q[~count] <= 1'b0;
    end
  end
endmodule
